class Membrane:
    def __init__(self, policy):
        self.revoked, self._proxies = False, WeakKeyDictionary()   # identity map
    def wrap(self, obj):
        if not isinstance(obj, (Graph, File)): return obj   # only capabilities
        if obj not in self._proxies:
            self._proxies[obj] = _Proxy(self, obj)          # one wrapper per raw
        return self._proxies[obj]
class _Proxy:
    def __getattribute__(self, name):                       # every attribute access
        m = object.__getattribute__(self, '_m')
        if m.revoked: raise PermissionError('revoked')
        return m.wrap(getattr(object.__getattribute__(self, '_t'), name))

