import wrapt

class DirMembrane(wrapt.ObjectProxy):
    def __init__(self, target, membrane):
        super().__init__(target)
        self._self_membrane = membrane          # wrapt convention: _self_* stays local

    def open(self, path):                        # mediated member
        m = self._self_membrane
        if m.revoked:
            raise PermissionError('revoked')
        return m.wrap(self.__wrapped__.open(path))   # wrap the way out
